import React, { useEffect, useState } from 'react'
import Button from 'components/ui/Buttons'
import StickyFooter from 'components/shared/StickyFooter'
import AdaptableCard from 'components/shared/AdaptableCard'
import Input from 'components/ui/Input'
import Select from 'components/ui/Select'
import { useNavigate, useParams } from 'react-router-dom'
import { Field, Form, Formik } from 'formik'
import * as Yup from 'yup'
import { FormContainer, FormItem } from 'components/ui'
import { apiProductGetSingle, apiProductPost, apiProductUpdate } from 'services/ProductService'
import { apiCategoryGetAll } from 'services/CategoryService'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'

const checkActive = [
    { value: 'Approved', label: 'Active' },
    { value: 'InActive', label: 'inactive' }
]

const validationSchema = Yup.object().shape({
    product_name: Yup.string().required('Product Name Is Required'),
    hsn_code: Yup.string().required('HSN Code Is Required'),
    hsn_name: Yup.string().required('HSN Name Is Required'),
    short_name: Yup.string().required('HSN Name Is Required'),
    category_id: Yup.string().required('Category Is Required'),
    grams: Yup.number().required('Disclosed Grams Is Required'),
    avg_grams: Yup.number().required('Average Grams Is Required'),
    rate: Yup.number().required('Rate Is Required'),
    anticipated_wastage: Yup.number().required('Anticipated Wastage Is Required'),
    cost: Yup.number().required('Cost Is Required'),
    tax_percentage: Yup.number().required('Tax Is Required'),
    status: Yup.string().required('Status Is Required'),
})

const AddProduct = () => {
    const [categoryOptions, setCategoryOptions] = useState([]);
    const [loading, setLoading] = useState(false)
    const [productData, setProductData] = useState(
        {
            product_name: '',
            barcode: '',
            hsn_code: '',
            hsn_name: '',
            short_name: '',
            category_id: '',
            grams: '',
            avg_grams: '',
            rate: '',
            anticipated_wastage: '',
            cost: '',
            tax_percentage: '',
            status: '',
            remarks: ''
        }
    )
    const navigate = useNavigate();
    const productId = useParams();

    console.log("Add Product.js Loading....")
    useEffect(() => {
        const promiseOptions = async () => {

            await apiCategoryGetAll().then(data => {
                const categories = data.rows;
                setCategoryOptions(categories.map(cat => {
                    return { value: cat.id, label: cat.category_name };
                }));
                setLoading(false);
            })

            return true
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
        if (categoryOptions.length === 0) {
            setLoading(true)
            promiseOptions()
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
        if (productId.productid) {
            async function fetchData() {
                await apiProductGetSingle(productId.productid).then(data => {
                    if (data.status === 200) {
                        // console.log(data.data['product'])
                        setProductData(data.data['product'])
                    }
                });
                return true
            }
            fetchData();
        }


    }, [])

    return (
        <>
            <Formik
                enableReinitialize={true}
                initialValues={productData}
                validationSchema={validationSchema}
                onSubmit={async (values, actions) => {
                    if (productId.productid) {
                        // console.log(values)
                        await apiProductUpdate({ values, ...{ id: productId.productid } }).then(data => {
                            console.log(data);
                            if (data.status === 200) {
                                actions.setSubmitting(false)
                                toast.push(
                                    <Notification
                                        title='Success'
                                        type='success'
                                        closable
                                    >
                                        {data.data['message']}
                                    </Notification>
                                )
                                actions.resetForm();
                                navigate('/product/product')
                            }
                        }).catch(error => {
                            let errorData = error.response['data']['error']['errors'];
                            if (error.response.status === 422) {
                                for (const errMsg in errorData) {
                                    actions.setFieldError(errMsg, errorData[errMsg]['message'])
                                    toast.push(
                                        <Notification
                                            title='Error'
                                            type='danger'
                                            closable
                                        >
                                            {errorData[errMsg]['message']}

                                        </Notification>
                                    )
                                }
                            } else if (error.response.status === 500) {
                                console.log(errorData)
                                toast.push(
                                    <Notification
                                        title='Error'
                                        type='danger'
                                        closable
                                    >
                                        {error.response.data['message']}

                                    </Notification>
                                )
                            }
                        })
                    } else {
                        await apiProductPost(values).then(data => {
                            if (data.status === 201) {
                                console.log(data);
                                actions.setSubmitting(false)
                                actions.resetForm();
                                toast.push(
                                    <Notification
                                        title='Success'
                                        type='success'
                                        closable
                                    >
                                        {data.data['message']}
                                    </Notification>
                                )
                                navigate('/product/product')
                            }
                        }).catch(error => {
                            let errorData = error.response['data']['error']['errors'];
                            actions.setSubmitting(false)
                            if (error.response.status === 422) {
                                for (const errMsg in errorData) {
                                    actions.setFieldError(errMsg, errorData[errMsg]['message'])
                                    toast.push(
                                        <Notification
                                            title='Error'
                                            type='danger'
                                            closable
                                        >
                                            {errorData[errMsg]['message']}

                                        </Notification>
                                    )
                                }
                            } else if (error.response.status === 500) {
                                console.log(errorData)
                                toast.push(
                                    <Notification
                                        title='Error'
                                        type='danger'
                                        closable
                                    >
                                        {error.response.data['message']}

                                    </Notification>
                                )
                            }
                        })
                    }
                }}
            >
                {({ values, touched, errors, isSubmitting }) => (
                    <Form>
                        <FormContainer layout='horizontal' labelWidth={120} >
                            <div className="mb-4 md:w-full m-auto">
                                <AdaptableCard className="card-shadow">
                                    {/* <h5>Product Imformation</h5> */}
                                    <h5> {productId.productid ? 'Edit' : 'Add New'} Product Imformation</h5>
                                    <p className="mb-6">{productId.productid ? 'Edit' : 'Add'} basic details of product</p>
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-x-8 gap-y-2 ">
                                        <FormItem
                                            asterisk
                                            label="Product Name"
                                            invalid={errors.product_name && touched.product_name}
                                            errorMessage={errors.product_name}
                                        >
                                            <Field
                                                type="text"
                                                name="product_name"
                                                placeholder="Product Name"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Short Name"
                                            invalid={errors.short_name && touched.short_name}
                                            errorMessage={errors.short_name}

                                        >
                                            <Field
                                                type="text"
                                                name="short_name"
                                                placeholder="Short Name"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="HSN Code"
                                            invalid={errors.hsn_code && touched.hsn_code}
                                            errorMessage={errors.hsn_code}
                                        >
                                            <Field
                                                type="text"
                                                name="hsn_code"
                                                placeholder="HSN Code"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="HSN Name"
                                            invalid={errors.hsn_name && touched.hsn_name}
                                            errorMessage={errors.hsn_name}

                                        >
                                            <Field
                                                type="text"
                                                name="hsn_name"
                                                placeholder="HSN Name"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            label="Barcode"
                                            invalid={errors.barcode && touched.barcode}
                                            errorMessage={errors.barcode}
                                        >
                                            <Field
                                                type="text"
                                                name="barcode"
                                                placeholder="Barcode"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Category"
                                            invalid={errors.category_id && touched.category_id}
                                            errorMessage={errors.category_id}
                                        >
                                            <Field name="category_id">
                                                {({ field, form }) => (
                                                    <Select
                                                        field={field}
                                                        form={form}
                                                        options={categoryOptions}
                                                        // onFocus={onFocus}
                                                        isLoading={loading}
                                                        value={categoryOptions.filter(
                                                            (option) => option.value === values.category_id
                                                        )}
                                                        onChange={(option) => {
                                                            return form.setFieldValue(
                                                                field.name,
                                                                option?.value
                                                            )
                                                        }}
                                                    />
                                                )}
                                            </Field>
                                        </FormItem>
                                    </div>
                                    <h5>Product Costing</h5>
                                    <p className="mb-6">{productId.productid ? 'Edit' : 'Add'} product selling amount as per grams</p>
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-x-8 gap-y-2">
                                        <FormItem
                                            asterisk
                                            label="Disclosed Grams"
                                            invalid={errors.grams && touched.grams}
                                            errorMessage={errors.grams}
                                        >
                                            <Field
                                                type="number"
                                                name="grams"
                                                placeholder="Disclosed Grams"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Avg Grams In Bar"
                                            invalid={errors.avg_grams && touched.avg_grams}
                                            errorMessage={errors.avg_grams}
                                        >
                                            <Field
                                                type="number"
                                                name="avg_grams"
                                                placeholder="Avg Grams In Bar"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Rate (In Rs)"
                                            invalid={errors.rate && touched.rate}
                                            errorMessage={errors.rate}
                                        >
                                            <Field
                                                type="number"
                                                name="rate"
                                                placeholder="Rate (In Rs)"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Anticipated Wastage"
                                            invalid={errors.anticipated_wastage && touched.anticipated_wastage}
                                            errorMessage={errors.anticipated_wastage}
                                        >
                                            <Field
                                                type="number"
                                                name="anticipated_wastage"
                                                placeholder="Anticipated Wastage (In %)"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Cost"
                                            invalid={errors.cost && touched.cost}
                                            errorMessage={errors.cost}
                                        >
                                            <Field
                                                type="number"
                                                name="cost"
                                                placeholder="Cost"
                                                component={Input}
                                            />
                                        </FormItem>
                                        <FormItem
                                            asterisk
                                            label="Tax"
                                            invalid={errors.tax_percentage && touched.tax_percentage}
                                            errorMessage={errors.tax_percentage}
                                        >
                                            <Field
                                                type="number"
                                                name="tax_percentage"
                                                placeholder="Tax"
                                                component={Input}
                                            />
                                        </FormItem>
                                    </div>
                                    <h5>Other Information</h5>
                                    <p className="mb-6">{productId.productid ? 'Edit' : 'Add'} final product status</p>
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-x-8 gap-y-2">
                                        <div>
                                            <FormItem
                                                asterisk
                                                label="Status"
                                                invalid={errors.status && touched.status}
                                                errorMessage={errors.status}
                                            >
                                                <Field name="status" >
                                                    {({ field, form }) => (
                                                        <Select
                                                            className='justify-items-start align-top items-start'
                                                            field={field}
                                                            form={form}
                                                            options={checkActive}
                                                            value={checkActive.filter(
                                                                (option) =>
                                                                    option.value ===
                                                                    values.status
                                                            )}
                                                            onChange={(option) =>
                                                                form.setFieldValue(
                                                                    field.name,
                                                                    option?.value
                                                                )
                                                            }
                                                        />
                                                    )}
                                                </Field>
                                            </FormItem>
                                        </div>
                                        <FormItem
                                            label="Remark"
                                            invalid={errors.remarks && touched.remarks}
                                            errorMessage={errors.remarks}
                                            className="md:col-span-2"
                                        >
                                            <Field
                                                name="remarks"
                                            >
                                                {({ field, form }) => {
                                                    return (
                                                        <Input
                                                            type="text"
                                                            field={field}
                                                            form={form}
                                                            // name={field.name}
                                                            value={field.value}
                                                            onChange={(option) =>
                                                                form.setFieldValue(
                                                                    field.name,
                                                                    option.target.value
                                                                )
                                                            }
                                                            textArea
                                                        />
                                                    )
                                                }}
                                            </Field>
                                        </FormItem>
                                    </div>
                                </AdaptableCard>
                            </div>
                        </FormContainer>
                        <StickyFooter
                            className="-mx-1 md:-mx-1 px-8 flex items-center justify-between py-4"
                            stickyClass="border bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700"
                        >
                            <div></div>
                            <div className="md:flex items-center">
                                <Button size="sm" type="submit" className="ltr:mr-3 rtl:ml-3" variant="solid" disabled={isSubmitting}>
                                    Save
                                </Button>
                                <Button size="sm" onClick={() => navigate('/product/product')}>
                                    Discard
                                </Button>
                            </div>
                        </StickyFooter>
                    </Form>)}
            </Formik>
        </>
    )
}

export default AddProduct
